def Q(k,u,q,o,a,e,note,**kw):
    y,n=map(int,k.split('-'))
    d=dict(k=k,y=y,yr=YR[y],n=n,u=u,src="공식",q=q,o=o,a=a,e=e,note=note); d.update(kw); return d
def E(a,ok,o=None):
    e=["틀리다."]*5; e[a-1]=ok
    for i,t in (o or {}).items(): e[i-1]=t
    return e
def M(a,ok,o=None):
    e=["맞다."]*5; e[a-1]=ok
    for i,t in (o or {}).items(): e[i-1]=t
    return e
